{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "2 <= n <= 200000",
      "description": "The number of cities n must be between 2 and 200,000 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(1 <= p[i] <= i - 1 for i in range(2, n + 1))",
      "description": "Each road description p_i must connect city i to a valid city p_i, where p_i is between 1 and i-1."
    },
    {
      "id": "P3",
      "expression": "len(p) == n - 1",
      "description": "The length of the road description list must be exactly n - 1."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout.split()) == n",
      "description": "The output must contain exactly n integers."
    },
    {
      "id": "Q2",
      "expression": "all(0 <= int(a) < 1000000007 for a in stdout.split())",
      "description": "Each output integer must be non-negative and less than 1,000,000,007."
    },
    {
      "id": "Q3",
      "expression": "stdout == ' '.join(map(str, a))",
      "description": "The output must match the computed number of ways for each city as the capital."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "0 <= m <= 10",
      "description": "The number of acquaintance relations m must be between 0 and 10 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(1 <= a <= 5 and 1 <= b <= 5 and a != b for a, b in acquaintances)",
      "description": "Each acquaintance pair (ai, bi) must consist of distinct integers between 1 and 5 inclusive."
    },
    {
      "id": "P3",
      "expression": "len(set(acquaintances)) == m",
      "description": "Each acquaintance pair must be unique and not repeated."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'WIN'",
      "description": "Output 'WIN' if there are three pairwise acquainted or three pairwise unacquainted people."
    },
    {
      "id": "Q2",
      "expression": "stdout == 'FAIL'",
      "description": "Output 'FAIL' if there are neither three pairwise acquainted nor three pairwise unacquainted people."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "interpreter",
    "signature": "tape: str -> str"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(tape, str)",
      "description": "The input 'tape' must be a string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output) == count('*' in tape for char in tape)",
      "description": "The output length corresponds to the number of '*' commands in the input tape."
    },
    {
      "id": "Q2",
      "expression": "all(0 <= cell < 256 for cell in data)",
      "description": "All data cell values must be within the range of 0 to 255."
    },
    {
      "id": "Q3",
      "expression": "output == expected_output",
      "description": "The output string must match the expected output based on the commands processed."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 1000",
      "description": "The number of houses n must be between 1 and 1000."
    },
    {
      "id": "P2",
      "expression": "0 <= p <= n",
      "description": "The number of pipes p must be between 0 and n."
    },
    {
      "id": "P3",
      "expression": "all(1 <= ai <= n and 1 <= bi <= n and ai != bi and 1 <= di <= 10**6 for ai, bi, di in pipes)",
      "description": "Each pipe must connect valid house indices with a positive diameter, and no house can have more than one incoming or outgoing pipe."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(t) + '\\n' + '\\n'.join(f'{tank} {tap} {diameter}' for tank, tap, diameter in sorted(tank_tap_pairs))",
      "description": "The output must contain the number of tank-tap pairs followed by each pair's details in sorted order."
    },
    {
      "id": "Q2",
      "expression": "t == len(tank_tap_pairs)",
      "description": "The number of tank-tap pairs t must match the length of the list of pairs."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2000",
      "description": "The number of employees n must be between 1 and 2000 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(-1 <= pi <= n for pi in p)",
      "description": "Each immediate manager pi must be either -1 or a valid employee number between 1 and n."
    },
    {
      "id": "P3",
      "expression": "len(p) == n",
      "description": "The list of immediate managers must contain exactly n entries."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(min_groups)",
      "description": "The output must be the minimum number of groups required to arrange the employees."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "has_subpattern",
    "signature": "string -> bool"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(string, str)",
      "description": "Input must be a string."
    },
    {
      "id": "P2",
      "expression": "len(string) > 0",
      "description": "Input string must not be empty."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "any(string == pattern * (len(string) // len(pattern)) for pattern in (string[:i] for i in range(1, len(string) // 2 + 1)))",
      "description": "Output is True if the string can be formed by repeating a shorter subpattern."
    },
    {
      "id": "Q2",
      "expression": "not any(string == pattern * (len(string) // len(pattern)) for pattern in (string[:i] for i in range(1, len(string) // 2 + 1)))",
      "description": "Output is False if the string cannot be formed by repeating a shorter subpattern."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "case_sensitive",
    "signature": "def case_sensitive(s: str) -> list"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(s, str)",
      "description": "Input s must be a string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value[0] == (all(c.islower() for c in s))",
      "description": "The first element of the return value indicates if all characters in s are lowercase."
    },
    {
      "id": "Q2",
      "expression": "return_value[1] == [c for c in s if not c.islower()]",
      "description": "The second element of the return value is a list of all characters in s that are not lowercase, in the order they appear."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 100000",
      "description": "The number of test cases T is between 1 and 100,000."
    },
    {
      "id": "P2",
      "expression": "1 <= n <= 100000",
      "description": "The number of villages n in each test case is between 1 and 100,000."
    },
    {
      "id": "P3",
      "expression": "sum(abs(D[i]) for i in range(n)) <= 1000000",
      "description": "The total number of villagers and dinosaurs across all test cases does not exceed 1,000,000."
    },
    {
      "id": "P4",
      "expression": "all(-10000 <= D[i] <= 10000 for i in range(n))",
      "description": "Each element in the array D is between -10,000 and 10,000."
    },
    {
      "id": "P5",
      "expression": "sum(D) == 0",
      "description": "The sum of the array D is zero, ensuring equal numbers of villagers and dinosaurs."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(min_grass)",
      "description": "The output is the minimum number of units of grass needed, represented as a string."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": "Solution",
    "function_name": "arrangeWords",
    "signature": "text: str -> str"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(text, str)",
      "description": "Input text must be a string."
    },
    {
      "id": "P2",
      "expression": "1 <= len(text) <= 10**5",
      "description": "The length of the input text must be between 1 and 100,000 characters."
    },
    {
      "id": "P3",
      "expression": "text[0].isupper() and all(c.islower() or c.isspace() for c in text[1:]) and '  ' not in text",
      "description": "The first letter of the text must be uppercase, all other letters must be lowercase, and words must be separated by a single space."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == ' '.join(sorted(words, key=lambda w: (len(w), original_index[w])))",
      "description": "The output text must contain the words sorted by length, maintaining original order for words of the same length."
    },
    {
      "id": "Q2",
      "expression": "stdout[0].isupper()",
      "description": "The first letter of the output text must be uppercase."
    },
    {
      "id": "Q3",
      "expression": "all(len(word) > 0 for word in stdout.split())",
      "description": "The output text must contain only non-empty words."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": "Solution",
    "function_name": "hasAllCodes",
    "signature": "def hasAllCodes(self, s: str, k: int) -> bool"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= len(s) <= 5 * 10**5",
      "description": "The length of the binary string s must be between 1 and 500,000."
    },
    {
      "id": "P2",
      "expression": "all(c in '01' for c in s)",
      "description": "The string s must consist only of '0's and '1's."
    },
    {
      "id": "P3",
      "expression": "1 <= k <= 20",
      "description": "The integer k must be between 1 and 20."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value == True",
      "description": "The function returns True if every binary code of length k is a substring of s."
    },
    {
      "id": "Q2",
      "expression": "return_value == False",
      "description": "The function returns False if at least one binary code of length k is not a substring of s."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": "Solution",
    "function_name": "flipLights",
    "signature": "def flipLights(self, n: int, m: int) -> int"
