  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout in {'Alice', 'Bob', 'Draw'}",
      "description": "The output must be either 'Alice', 'Bob', or 'Draw' for each test case."
    },
    {
      "id": "Q2",
      "expression": "len(stdout.splitlines()) == t",
