  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "date_checker",
    "signature": "date_checker(date: str) -> bool"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(date, str)",
      "description": "The input 'date' must be a string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value == (len(date) == 16 and date[2] == '-' and date[5] == '-' and date[10] == ':' and all(part.isdigit() for part in [date[:2], date[3:5], date[6:10], date[11:13], date[14:16]]) and 1 <= int(date[:2]) <= 31 and 1 <= int(date[3:5]) <= 12 and 0 <= int(date[11:13]) < 24 and 0 <= int(date[14:16]) < 60)",
      "description": "The output 'return_value' is true if 'date' matches the format 'DD-MM-YYYY HH:MM' with valid day, month, hour, and minute values; otherwise, it is false."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "0 <= n <= 300000",
      "description": "The number of initial strings n must be between 0 and 300,000."
    },
    {
      "id": "P2",
      "expression": "0 <= m <= 300000",
      "description": "The number of queries m must be between 0 and 300,000."
    },
    {
      "id": "P3",
      "expression": "len(s) > 0 and all(c in 'abc' for c in s)",
      "description": "Each string s in the input must be non-empty and consist only of characters 'a', 'b', and 'c'."
    },
    {
      "id": "P4",
      "expression": "sum(len(s) for s in initial_strings) <= 600000",
      "description": "The total length of all initial strings must not exceed 600,000."
    },
    {
      "id": "P5",
      "expression": "sum(len(q) for q in queries) <= 600000",
      "description": "The total length of all query strings must not exceed 600,000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'YES\\n' * count_yes + 'NO\\n' * count_no",
      "description": "For each query, output 'YES' if a matching string exists in memory, otherwise output 'NO'."
    },
    {
      "id": "Q2",
      "expression": "count_yes + count_no == m",
      "description": "The total number of outputs must equal the number of queries m."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 10**5",
      "description": "The number of people n must be between 1 and 100,000."
    },
    {
      "id": "P2",
      "expression": "0 <= m <= 3 * 10**5",
      "description": "The number of debts m must be between 0 and 300,000."
    },
    {
      "id": "P3",
      "expression": "all(1 <= u <= n and 1 <= v <= n and u != v for u, v, d in debts)",
      "description": "Each debt must involve two distinct people within the range of 1 to n."
    },
    {
      "id": "P4",
      "expression": "all(1 <= d <= 10**9 for u, v, d in debts)",
      "description": "Each debt amount must be between 1 and 1,000,000,000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "m <= 3 * 10**5",
      "description": "The number of debts after consolidation must not exceed 300,000."
    },
    {
      "id": "Q2",
      "expression": "all(1 <= u_i <= n and 1 <= v_i <= n and u_i != v_i and 0 < d_i <= 10**18 for u_i, v_i, d_i in output_debts)",
      "description": "Each output debt must involve two distinct people and have a positive amount not exceeding 10^18."
    },
    {
      "id": "Q3",
      "expression": "len(set((u_i, v_i) for u_i, v_i, d_i in output_debts)) == len(output_debts)",
      "description": "Each pair of people can appear at most once in the output debts."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "count_correct_characters",
    "signature": "def count_correct_characters(correct: str, guess: str) -> int"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "len(correct) == len(guess)",
      "description": "The lengths of the correct word and the guessed word must be equal."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value == sum(1 for i in range(len(correct)) if correct[i] == guess[i])",
      "description": "The return value is the count of letters that are in the correct position."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "range_parser",
    "signature": "string -> list[int]"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(string, str)",
      "description": "The input must be a string."
    },
    {
      "id": "P2",
      "expression": "all(token.strip() for token in string.split(',') if token.strip())",
      "description": "The string must contain valid tokens separated by commas."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "all(isinstance(x, int) and x > 0 for x in return_value)",
      "description": "All elements in the output list must be positive integers."
    },
    {
      "id": "Q2",
      "expression": "len(return_value) == sum(1 for token in string.split(',') for x in parse_token(token.strip()))",
      "description": "The output list must contain integers corresponding to the parsed tokens."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 300000",
      "description": "The length of the string n must be between 1 and 300,000."
    },
    {
      "id": "P2",
      "expression": "1 <= m <= 300000",
      "description": "The number of queries m must be between 1 and 300,000."
    },
    {
      "id": "P3",
      "expression": "len(s) == n and all(c in 'abcdefghijklmnopqrstuvwxyz.' for c in s)",
      "description": "The string s must have a length of n and consist only of lowercase letters and period signs."
    },
    {
      "id": "P4",
      "expression": "all(1 <= x_i <= n and (c_i in 'abcdefghijklmnopqrstuvwxyz.' for x_i, c_i in queries))",
      "description": "Each query must specify a valid position x_i within the string and a character c_i that is either a lowercase letter or a period."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(f(s))",
      "description": "After each query, the output must be the minimum number of operations f(s) required to eliminate consecutive periods in the updated string."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "f(s) >= 0",
      "description": "The function f(s) must always return a non-negative integer."
    }
  ]
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= N <= 100000",
      "description": "The number of vertices N must be between 1 and 100000."
